import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"OmniRouter: Taming Model Chaos","description":"Why I built OmniRouter — the story of turning model churn into a config file, with load balancing and failover in one Go binary.","frontmatter":{"title":"OmniRouter: Taming Model Chaos","description":"Why I built OmniRouter — the story of turning model churn into a config file, with load balancing and failover in one Go binary."},"headers":[],"relativePath":"en/vibe-stories/story-2/index.md","filePath":"en/vibe-stories/story-2/index.md"}`),a={name:`en/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="omnirouter-taming-model-chaos" tabindex="-1">OmniRouter: Taming Model Chaos <a class="header-anchor" href="#omnirouter-taming-model-chaos" aria-label="Permalink to “OmniRouter: Taming Model Chaos”">​</a></h1><p>The AI ecosystem moves at scroll speed. The model that powered my week is deprecated by Friday, prices flip, free tiers appear and vanish. My apps kept breaking for reasons that had nothing to do with my code — so I made the churn someone else&#39;s problem. That someone is <strong><a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a></strong>.</p><h2 id="the-insight" tabindex="-1">The insight <a class="header-anchor" href="#the-insight" aria-label="Permalink to “The insight”">​</a></h2><p>The OpenAI chat-completions format won. It is the interface every client already speaks. So OmniRouter presents exactly that interface to your app, and speaks whatever each upstream needs on the other side — GLM, Qwen, DeepSeek, custom endpoints. Your code changes <strong>never</strong>; the config file changes weekly.</p><h2 id="the-hard-parts" tabindex="-1">The hard parts <a class="header-anchor" href="#the-hard-parts" aria-label="Permalink to “The hard parts”">​</a></h2><ul><li><strong>Streaming honesty</strong> — relaying SSE token-for-token without buffering surprises took careful plumbing.</li><li><strong>Failure detection</strong> — distinguishing &quot;model is slow&quot; from &quot;model is dying&quot; needs rolling health windows, not single-shot probes.</li><li><strong>Fair rotation</strong> — weighted round-robin with quotas, so cheap capacity gets used before premium tokens.</li></ul><p>Together with the <a href="/Usf/en/projects/glm-free-api/">free-api bridges</a>, OmniRouter gives me something absurd on paper and essential in practice: a multi-model AI stack with <strong>zero monthly cost</strong> and one config file to rule them all.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};